html:
{#
  Student Journal Voucher — Print Format
  App     : dux_voucher | Frappe v16 / ERPNext v16
  Module  : Dux Voucher
  Style   : Same family as the Student Fee Receipt / Refund vouchers, with a
            violet accent. The title follows the purpose (Fee Transfer
            Voucher, Fee Debit Note, Fine Voucher, Fee Concession Voucher …).
            The Particulars table prints the entry exactly as posted —
            Dr / Cr per ledger, Tally style — plus the institute's own entry
            on a transfer, and the student's balance before and after.
#}

{%- set company_doc = frappe.get_doc("Company", doc.company) %}
{%- set _raw_logo   = company_doc.get("custom_voucher_print_logo") %}
{%- if _raw_logo %}
  {%- set logo_url = frappe.utils.get_url(_raw_logo) %}
{%- else %}
  {%- set logo_url = frappe.utils.get_url("/assets/dux_voucher/images/dv_logo.png") %}
{%- endif %}
{%- set currency    = company_doc.get("default_currency") or "INR" %}
{%- set footer_note = company_doc.get("custom_voucher_footer_note") or
    "This is a computer-generated voucher. Valid without physical stamp unless specified by policy." %}

{%- set _titles = {
    "Transfer to Institute":       "Fee Transfer Voucher",
    "Fee Charged":                 "Fee Debit Note",
    "Fine / Penalty":              "Fine / Penalty Voucher",
    "Concession":                  "Fee Concession Voucher",
    "Transfer to Another Student": "Student Transfer Voucher",
    "Other Debit to Student":      "Student Debit Note",
    "Other Credit to Student":     "Student Credit Note",
} %}
{%- set _title = _titles.get(doc.purpose) or "Student Journal Voucher" %}
{%- set _credit = doc.purpose in ["Concession", "Other Credit to Student"] %}
{%- set _abbr = company_doc.abbr %}
{%- set _stu_acc = "Admission/Registration Fee (Provisional) - " ~ _abbr %}
{%- set _owner_name = frappe.db.get_value("User", doc.owner, "full_name") or doc.owner %}

{%- macro money(v) -%}{{ frappe.utils.fmt_money(v, currency=currency) }}{%- endmacro %}
{%- macro bal(v) -%}
  {%- if (v or 0)|abs < 0.005 -%}Nil
  {%- elif v > 0 -%}{{ frappe.utils.fmt_money(v, currency=currency) }} Cr
  {%- else -%}{{ frappe.utils.fmt_money(-v, currency=currency) }} Dr{%- endif -%}
{%- endmacro %}

<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>{{ _title }} — {{ doc.name }}</title>
<style>
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
  body { font-family: 'Segoe UI', Arial, sans-serif; font-size: 12px; color: #1a1a2e; background: #fff; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
  .page { width: 100%; max-width: 210mm; margin: 0 auto; padding: 5mm 8mm 6mm; }

  .header { display: grid; grid-template-columns: 90px 1fr 190px; gap: 10px; align-items: flex-start; padding-bottom: 10px; border-bottom: 2.5px solid #6D28D9; }
  .logo-wrap img { width: 82px; height: auto; max-height: 60px; object-fit: contain; display: block; }
  .co-name { font-size: 14px; font-weight: 700; color: #6D28D9; margin-bottom: 4px; }
  .co-meta { font-size: 9.5px; color: #555; line-height: 1.65; }
  .doc-title-block { text-align: right; }
  .vch-label { font-size: 13px; font-weight: 700; color: #6D28D9; letter-spacing: 1px; text-transform: uppercase; }
  .doc-no-pill { display: inline-block; margin-top: 5px; background: #EDE9FE; color: #2E1065; font-size: 11px; font-weight: 700; padding: 3px 10px; border-radius: 4px; }
  .date-label { font-size: 8.5px; color: #888; text-transform: uppercase; letter-spacing: 0.5px; margin-top: 7px; }
  .date-value { font-size: 12px; font-weight: 600; color: #1a1a2e; margin-top: 2px; }

  .meta-strip { display: grid; grid-template-columns: 1fr 1fr 1fr; border: 0.5px solid #ddd6fe; border-top: none; }
  .mc { padding: 7px 11px; border-right: 0.5px solid #ddd6fe; }
  .mc:last-child { border-right: none; }
  .mc-label { font-size: 8.5px; text-transform: uppercase; letter-spacing: 0.6px; color: #888; margin-bottom: 3px; }
  .mc-value { font-size: 11px; font-weight: 600; color: #1a1a2e; }

  .sec-title { background: #f5f3ff; border-top: 0.5px solid #ddd6fe; border-bottom: 0.5px solid #ddd6fe; padding: 5px 11px; font-size: 8.5px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.7px; color: #6D28D9; margin-top: 6px; }

  table.kv { width: 100%; border-collapse: collapse; border: 0.5px solid #ddd6fe; border-top: none; }
  table.kv td { padding: 7px 11px; border-bottom: 0.5px solid #ede9fe; vertical-align: middle; font-size: 11px; color: #1a1a2e; }
  table.kv tr:last-child td { border-bottom: none; }
  table.kv td.k { width: 170px; font-size: 8.5px; text-transform: uppercase; letter-spacing: 0.5px; color: #888; font-weight: 700; border-right: 0.5px solid #ede9fe; background: #faf8ff; }
  table.kv td.v { font-size: 12px; font-weight: 600; color: #1a1a2e; }
  table.kv td.v-big { font-size: 14px; font-weight: 700; color: #6D28D9; }

  table.lines { width: 100%; border-collapse: collapse; border: 0.5px solid #ddd6fe; border-top: none; }
  table.lines thead th { background: #faf8ff; padding: 7px 11px; font-size: 8.5px; text-transform: uppercase; letter-spacing: 0.5px; color: #888; font-weight: 700; border-bottom: 0.5px solid #ddd6fe; text-align: left; }
  table.lines thead th.r { text-align: right; width: 120px; }
  table.lines td { padding: 8px 11px; border-bottom: 0.5px solid #ede9fe; font-size: 11px; }
  table.lines td.k { color: #1a1a2e; font-weight: 600; }
  table.lines td.k .sub { display: block; font-weight: 400; font-size: 9.5px; color: #6D28D9; margin-top: 1px; }
  table.lines td.r { text-align: right; font-variant-numeric: tabular-nums; font-family: 'Courier New', monospace; font-size: 11.5px; white-space: nowrap; }
  table.lines tr.total td { background: #f5f3ff; font-weight: 700; color: #6D28D9; border-top: 1.5px solid #6D28D9; }

  .bal-row { display: grid; grid-template-columns: 1fr 1fr; border: 0.5px solid #ddd6fe; border-top: none; }
  .bal-cell { padding: 7px 11px; border-right: 0.5px solid #ddd6fe; }
  .bal-cell:last-child { border-right: none; }
  .bal-label { font-size: 8.5px; text-transform: uppercase; letter-spacing: 0.5px; color: #888; margin-bottom: 2px; }
  .bal-value { font-size: 12px; font-weight: 700; color: #1a1a2e; }

  .totals-bar { display: flex; justify-content: space-between; align-items: center; padding: 9px 11px; border: 0.5px solid #ddd6fe; border-top: 1.5px solid #6D28D9; background: #f5f3ff; margin-top: 6px; }
  .w-label { font-size: 8.5px; text-transform: uppercase; letter-spacing: 0.5px; color: #888; margin-bottom: 3px; }
  .w-value { font-size: 10.5px; font-style: italic; color: #6D28D9; font-weight: 600; max-width: 340px; }
  .a-label { font-size: 8.5px; text-transform: uppercase; letter-spacing: 0.5px; color: #888; margin-bottom: 2px; text-align: right; }
  .a-value { font-size: 22px; font-weight: 700; color: #6D28D9; text-align: right; }

  .remarks-block { border: 0.5px solid #ddd6fe; border-top: none; padding: 7px 11px; }
  .r-label { font-size: 8.5px; text-transform: uppercase; letter-spacing: 0.5px; color: #888; margin-bottom: 3px; }
  .r-value { font-size: 11px; color: #333; line-height: 1.5; }

  .sig-strip { display: grid; grid-template-columns: 1fr 1fr 1fr; border: 0.5px solid #ddd6fe; margin-top: 14px; }
  .sig-cell { padding: 7px 14px 9px; border-right: 0.5px solid #ddd6fe; text-align: center; }
  .sig-cell:last-child { border-right: none; }
  .sig-space { height: 34px; }
  .sig-line { border-top: 1px solid #6D28D9; margin-bottom: 4px; }
  .sig-label { font-size: 8.5px; text-transform: uppercase; letter-spacing: 0.6px; color: #555; }
  .sig-name  { font-size: 9px; color: #6D28D9; font-weight: 600; margin-top: 2px; }

  .cancelled { margin-top: 6px; padding: 6px 11px; background: #fef2f2; color: #991b1b; font-weight: 700; font-size: 11px; text-align: center; letter-spacing: 1px; }

  .page-footer { margin-top: 10px; padding-top: 8px; border-top: 0.5px solid #ddd6fe; display: flex; justify-content: space-between; align-items: center; }
  .page-footer .note { font-size: 8.5px; color: #aaa; font-style: italic; max-width: 480px; }
  .page-footer .brand { font-size: 8.5px; color: #aaa; white-space: nowrap; }
  .page-footer .brand strong { color: #6D28D9; }

  @media print {
    body { background: white; }
    .page { padding: 3mm 5mm; margin: 0; width: 100%; max-width: 100%; }
    @page { size: A4; margin: 10mm; }
  }
</style>
</head>
<body>
<div class="page">

  <div class="header">
    <div class="logo-wrap">
      <img src="{{ logo_url }}" alt="{{ company_doc.company_name or doc.company }}">
    </div>
    <div>
      <div class="co-name">{{ company_doc.company_name or doc.company }}</div>
      <div class="co-meta">
        {%- if company_doc.get("gstin") %}GSTIN: {{ company_doc.gstin }}{%- if company_doc.get("tax_id") %} &nbsp;|&nbsp; PAN: {{ company_doc.tax_id }}{%- endif %}<br>{%- elif company_doc.get("tax_id") %}PAN: {{ company_doc.tax_id }}<br>{%- endif %}
        {%- set addr_id = frappe.db.get_value("Dynamic Link", {"link_doctype": "Company", "link_name": company_doc.name, "parenttype": "Address"}, "parent") %}
        {%- if addr_id %}
          {%- set a = frappe.get_doc("Address", addr_id) %}
          {{ [a.address_line1, a.address_line2, a.city, a.state, a.pincode] | select | join(", ") }}<br>
        {%- endif %}
        {%- if company_doc.get("phone_no") %}Ph: {{ company_doc.phone_no }}{%- endif %}{%- if company_doc.get("phone_no") and company_doc.get("email") %} &nbsp;|&nbsp; {%- endif %}{%- if company_doc.get("email") %}{{ company_doc.email }}{%- endif %}
      </div>
    </div>
    <div class="doc-title-block">
      <div class="vch-label">{{ _title }}</div>
      <div><span class="doc-no-pill">{{ doc.name }}</span></div>
      <div class="date-label">Date</div>
      <div class="date-value">{{ frappe.format(doc.posting_date, {"fieldtype": "Date"}) }}</div>
    </div>
  </div>

  <div class="meta-strip">
    <div class="mc">
      <div class="mc-label">Purpose</div>
      <div class="mc-value">{{ doc.purpose }}</div>
    </div>
    <div class="mc">
      <div class="mc-label">Student Account</div>
      <div class="mc-value">{{ "Credited" if _credit else "Debited" }}</div>
    </div>
    <div class="mc">
      <div class="mc-label">{{ "Transferred To" if doc.purpose == "Transfer to Institute" else "Ledger Head" }}</div>
      <div class="mc-value">{{ doc.to_company if doc.purpose == "Transfer to Institute" else "Admission/Registration Fee (Provisional)" }}</div>
    </div>
  </div>

  {%- if doc.docstatus == 2 %}<div class="cancelled">CANCELLED</div>{%- endif %}

  <div class="sec-title">Student</div>
  <table class="kv">
    <tr><td class="k">Student Name</td><td class="v v-big">{{ doc.student_name or doc.student }}</td></tr>
    <tr><td class="k">Father's Name</td><td class="v">{{ doc.father_name or "&#8212;" }}</td></tr>
    <tr><td class="k">Course</td><td class="v">{{ doc.course or "&#8212;" }}</td></tr>
    <tr><td class="k">Student ID</td><td class="v">{{ doc.student }}</td></tr>
    {%- if doc.purpose == "Transfer to Another Student" %}
    <tr><td class="k">Transferred To Student</td><td class="v">{{ doc.to_student_name or doc.to_student }} ({{ doc.to_student }})</td></tr>
    {%- endif %}
  </table>

  <div class="sec-title">Particulars</div>
  <table class="lines">
    <thead><tr><th>Ledger</th><th class="r">Debit</th><th class="r">Credit</th></tr></thead>
    <tbody>
      {%- set stu_dr = 0 if _credit else doc.total_amount %}
      {%- set stu_cr = doc.total_amount if _credit else 0 %}
      <tr>
        <td class="k">{{ _stu_acc }}<span class="sub">{{ doc.student_name or doc.student }} &middot; {{ doc.student }}</span></td>
        <td class="r">{{ money(stu_dr) if stu_dr else "" }}</td>
        <td class="r">{{ money(stu_cr) if stu_cr else "" }}</td>
      </tr>
      {%- if doc.purpose == "Transfer to Institute" %}
      <tr>
        <td class="k">{{ doc.from_branch_account }}<span class="sub">Inter-company &middot; {{ doc.to_company }}</span></td>
        <td class="r"></td><td class="r">{{ money(doc.total_amount) }}</td>
      </tr>
      {%- elif doc.purpose == "Transfer to Another Student" %}
      <tr>
        <td class="k">{{ _stu_acc }}<span class="sub">{{ doc.to_student_name or doc.to_student }} &middot; {{ doc.to_student }}</span></td>
        <td class="r"></td><td class="r">{{ money(doc.total_amount) }}</td>
      </tr>
      {%- else %}
      {%- for row in doc.heads %}
      <tr>
        <td class="k">{{ row.account }}{%- if row.remarks %}<span class="sub">{{ row.remarks }}</span>{%- endif %}</td>
        <td class="r">{{ money(row.amount) if _credit else "" }}</td>
        <td class="r">{{ "" if _credit else money(row.amount) }}</td>
      </tr>
      {%- endfor %}
      {%- endif %}
      <tr class="total"><td class="k">Total</td><td class="r">{{ money(doc.total_amount) }}</td><td class="r">{{ money(doc.total_amount) }}</td></tr>
    </tbody>
  </table>

  {%- if doc.purpose == "Transfer to Institute" %}
  <div class="sec-title">Entry in the books of {{ doc.to_company }}</div>
  <table class="lines">
    <thead><tr><th>Ledger</th><th class="r">Debit</th><th class="r">Credit</th></tr></thead>
    <tbody>
      <tr><td class="k">{{ doc.to_branch_account }}<span class="sub">Inter-company &middot; {{ doc.company }}</span></td>
        <td class="r">{{ money(doc.total_amount) }}</td><td class="r"></td></tr>
      <tr><td class="k">{{ doc.to_account }}{%- if doc.to_student %}<span class="sub">{{ doc.to_student_name or doc.to_student }} &middot; {{ doc.to_student }}</span>{%- endif %}</td>
        <td class="r"></td><td class="r">{{ money(doc.total_amount) }}</td></tr>
      {%- if doc.to_company_je %}
      <tr><td class="k" colspan="3" style="font-weight:400;color:#888;font-size:9.5px">Journal Entry {{ doc.to_company_je }}</td></tr>
      {%- endif %}
    </tbody>
  </table>
  {%- endif %}

  <div class="bal-row">
    <div class="bal-cell"><div class="bal-label">Student balance before</div><div class="bal-value">{{ bal(doc.balance_before) }}</div></div>
    <div class="bal-cell"><div class="bal-label">Student balance after</div><div class="bal-value">{{ bal(doc.balance_after) }}</div></div>
  </div>

  <div class="totals-bar">
    <div>
      <div class="w-label">Amount in words</div>
      <div class="w-value">
        {%- set _words = frappe.utils.money_in_words(doc.total_amount, main_currency=currency) or "&#8212;" %}
        {{ _words.replace("INR ", "").replace("USD ", "").replace("EUR ", "") if _words != "&#8212;" else "&#8212;" }}
      </div>
    </div>
    <div>
      <div class="a-label">{{ "Amount Credited" if _credit else "Amount Debited" }}</div>
      <div class="a-value">{{ money(doc.total_amount) }}</div>
    </div>
  </div>

  {%- set _narr = doc.remarks or "" %}
  {%- if not _narr and doc.backend_je %}{%- set _narr = frappe.db.get_value("Journal Entry", doc.backend_je, "user_remark") or "" %}{%- endif %}
  {%- if _narr %}
  <div class="remarks-block">
    <div class="r-label">Narration</div>
    <div class="r-value">{{ _narr }}</div>
  </div>
  {%- endif %}

  <div class="sig-strip">
    <div class="sig-cell"><div class="sig-space"></div><div class="sig-line"></div><div class="sig-label">Prepared By</div><div class="sig-name">{{ _owner_name }}</div></div>
    <div class="sig-cell"><div class="sig-space"></div><div class="sig-line"></div><div class="sig-label">Verified By</div></div>
    <div class="sig-cell"><div class="sig-space"></div><div class="sig-line"></div><div class="sig-label">Authorised Signatory</div></div>
  </div>

  <div class="page-footer">
    <div class="note">{{ footer_note }}</div>
    <div class="brand">Powered by <strong>DUX DigiTech</strong></div>
  </div>

</div>
</body>
</html>
